import type { BanhMiBlock, BanhMiPlugin } from "../type";
import { writer } from "../writers";

export interface TSPluginOptions {
  /** Overrides the bake() outDir for this plugin only. */
  outDir?: string;
  /** Output file name. Defaults to index.ts. */
  fileName?: string;
}

const HEADER =
  "// This file is auto-generated by BanhMi. Do not edit this file directly.\n";

function render(kind: "Domain" | "View", name: string, blocks: BanhMiBlock[]) {
  const value = blocks.map((b) => b.content).join("\n");
  return [
    "/**",
    ` * # About\n`,
    ` * ${kind}: ${name}\n`,
    ` * Blocks: ${blocks.length}\n`,
    ` * Length: ${value.length}\n`,
    ` * # Content\n`,
    `${value}`,
    " */",
    `export const ${name} = ${JSON.stringify(value)} as const;`,
    "",
  ].join("\n");
}

/**
 * # TS Plugin
 *
 * Generates BanhMi resources in a single TypeScript file.
 */
export const TSPlugin =
  (options: TSPluginOptions = {}): BanhMiPlugin =>
  async ({ props, lock }) => {
    const body = [
      ...Object.entries(lock.domains).map(([name, blocks]) =>
        render("Domain", name, blocks),
      ),
      ...Object.entries(lock.views).map(([name, blocks]) =>
        render("View", name, blocks),
      ),
    ].join("\n");

    try {
      await writer(
        { ...props, outDir: options.outDir ?? props.outDir },
        options.fileName ?? "index.ts",
        HEADER + "\n" + body,
      );
    } catch (e) {
      console.error(e);
    }
  };
